fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    // Assuming s2.len() == n and s3.len() == n as given by the problem statement.
    // Also assuming 3 * n fits within i32::MAX, so usize overflow is not a concern for allocation here.

    let mut res = Vec::with_capacity(3 * n);
    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }
    res
}